  VerifySimpleAtoiBad<int8_t>(std::numeric_limits<int16_t>::min());
  VerifySimpleAtoiBad<int8_t>(std::numeric_limits<int16_t>::max());

  // SimpleAtoi(absl::string_view, uint8_t)
  VerifySimpleAtoiGood<uint8_t>(0, 0);

